const game = new GF.Game({ id: 'core-awakening', title: 'Core Awakening', width: 960, height: 540, palette: ['#00BFFF', '#FFC30B', '#FF5733', '#C0C0C0'], background: '#0b0e1a' });

let player, enemies, particles, lootChoices, scoreTimer;

function createEnemy(x, y) {
  return { x, y, size: 30, color: game.palette[2], hp: 3, attackTimer: 0, type: 'basic', attackPattern: 0 };
}

function createLootChoice(x, y) {
  return { x, y, size: 20, color: game.palette[1], active: false };
}

function resetGame() {
  player = { x: game.W / 2, y: game.H / 2, size: 20, color: game.palette[0], hp: 5, speed: 200 };
  enemies = [createEnemy(100, 100)];
  lootChoices = [createLootChoice(300, 300)];
  particles = [];
  scoreTimer = 0;
}

function updatePlayer(dt) {
  const speed = player.speed * dt;
  if (game.input.keys['KeyW']) player.y -= speed;
  if (game.input.keys['KeyS']) player.y += speed;
  if (game.input.keys['KeyA']) player.x -= speed;
  if (game.input.keys['KeyD']) player.x += speed;
  player.x = GF.math.clamp(player.x, player.size, game.W - player.size);
  player.y = GF.math.clamp(player.y, player.size, game.H - player.size);
}

function updateEnemies(dt) {
  for (const enemy of enemies) {
    enemy.attackTimer += dt;
    if (enemy.attackTimer > 1) {
      enemy.attackTimer = 0;
      game.hitStop(0.1);
      // Create attack particle effect
      game.burst(enemy.x, enemy.y, { count: 5, speed: 50, size: 4, life: 0.5, colors: [enemy.color], gravity: 0 });
    }
  }
}

function updateLootChoices(dt) {
  for (const loot of lootChoices) {
    if (loot.active && game.input.pressed('PointerDown')) {
      game.addScore(1);
      game.flash('#FFC30B', 0.5);
      loot.active = false;
      // Create loot particle effect
      game.burst(loot.x, loot.y, { count: 10, speed: 60, size: 3, life: 0.5, colors: [loot.color], gravity: 0 });
    }
  }
}

function updateParticles(dt) {
  particles = particles.filter(p => p.life > 0);
  for (const p of particles) {
    p.life -= dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
  }
}

function drawBackground(ctx) {
  // Create a dynamic gradient background
  const gradient = ctx.createLinearGradient(0, 0, 0, game.H);
  gradient.addColorStop(0, '#0b0e1a');
  gradient.addColorStop(1, '#1c2331');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, game.W, game.H);
  // Add parallax effect
  ctx.save();
  ctx.translate(0, Math.sin(game.time) * 5);
  ctx.fillStyle = '#20232a';
  ctx.fillRect(0, 100, game.W, 10);
  ctx.fillRect(0, 300, game.W, 10);
  ctx.restore();
}

function drawPlayer(ctx) {
  ctx.fillStyle = player.color;
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.size, 0, GF.math.TAU);
  ctx.fill();
  // Draw player outline
  ctx.strokeStyle = '#FFFFFF';
  ctx.lineWidth = 2;
  ctx.stroke();
}

function drawEnemies(ctx) {
  for (const enemy of enemies) {
    ctx.fillStyle = enemy.color;
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.size, 0, GF.math.TAU);
    ctx.fill();
    // Draw enemy outline
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 2;
    ctx.stroke();
  }
}

function drawLootChoices(ctx) {
  for (const loot of lootChoices) {
    if (loot.active) {
      ctx.fillStyle = loot.color;
      ctx.beginPath();
      ctx.arc(loot.x, loot.y, loot.size, 0, GF.math.TAU);
      ctx.fill();
      // Draw loot outline
      ctx.strokeStyle = '#FFFFFF';
      ctx.lineWidth = 2;
      ctx.stroke();
    }
  }
}

function drawParticles(ctx) {
  for (const p of particles) {
    ctx.fillStyle = p.color;
    ctx.globalAlpha = p.life;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size, 0, GF.math.TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawHUD(ctx) {
  // Draw HUD background
  GF.Draw.roundRect(ctx, 10, 10, 940, 60, 10, 'rgba(0,0,0,0.5)');
  GF.Draw.text(ctx, 'HP: ' + player.hp, 20, 30, { size: 20, color: '#fff', align: 'left' });
  GF.Draw.text(ctx, 'Score: ' + game.score, game.W - 20, 30, { size: 20, color: '#fff', align: 'right' });
  GF.Draw.text(ctx, 'Objective: Dismantle enemies', game.W / 2, 30, { size: 20, color: '#fff', align: 'center' });
  GF.Draw.text(ctx, 'Controls: WASD to move, Click to shoot', game.W / 2, 50, { size: 16, color: '#fff', align: 'center' });
}

game.add('play', {
  init() {
    resetGame();
  },
  reset() {
    resetGame();
  },
  update(dt) {
    updatePlayer(dt);
    updateEnemies(dt);
    updateLootChoices(dt);
    updateParticles(dt);
    scoreTimer += dt;
    if (scoreTimer > 1) {
      game.addScore(1);
      scoreTimer = 0;
    }
  },
  draw(ctx) {
    drawBackground(ctx);
    drawPlayer(ctx);
    drawEnemies(ctx);
    drawLootChoices(ctx);
    drawParticles(ctx);
    drawHUD(ctx);
  }
});

game.titleScreen({ subtitle: 'Press any key to start', onStart: () => game.go('play') });
